Aquí te presento una función en C++ que convierte texto con formato Markdown a HTML, usando la biblioteca estándar de C++:

```cpp
#include <iostream>
#include <string>
#include <regex>

// Función para convertir texto con formato Markdown a HTML
std::string markdownToHtml(const std::string& markdown) {
    // Reemplazar los enlaces
    std::string html = regex_replace(markdown, std::regex("\\[(\\S*?)\\]\\((\\S*?)\\)"), R"($1<a href="$2">$1</a>)");

    // Reemplazar las citas
    html = regex_replace(html, std::regex(">(\\S*?)</blockquote>"), R"(<p>$1</p>)");

    // Reemplazar los títulos
    html = regex_replace(html, std::regex("^(#{1,6})\\s+(.+)$"), R"(<h$1>$2</h$1>)");

    // Reemplazar los listados
    html = regex_replace(html, std::regex("^(\\*|\\+|\\-)\\s+(.+)$"), R"(<li>$1</li>)");
    html = regex_replace(html, std::regex("^\\s*(\\d+)\\.\\s+(.+)$"), R"(<li>$2</li>)");
    html = regex_replace(html, std::regex("^\\s*(\\d+)\\.\\s+(.+)$", std::regex::format), R"(<ol><li>$2</li></ol>)");

    // Reemplazar los código fuente
    html = regex_replace(html, std::regex("```(\\w*)\\n(.*?)\\n```"), R"<pre><code class='$1'>$2</code></pre>");

    // Reemplazar los énfasis
    html = regex_replace(html, std::regex("_(\\S*?)_"), R"<em>$1</em>");
    html = regex_replace(html, std::regex("__(\\S*?)__"), R"<strong>$1</strong>");

    return html;
}

// Ejemplo de uso
int main() {
    std::string markdown = "Este es un **ejemplo** de texto con formato [Markdown](https://daringfireball.net/projects/markdown/). \n\n Aquí hay un enlace: [Google](https://www.google.com/).\n\n También hay una cita: \n> Esta es una cita.\n\n Y un título H1: # Título H1\n\n Un título H2: ## Título H2\n\n Un título H3: ### Título H3\n\n Un listado:\n- Item 1\n- Item 2\n1. Item 3\n2. Item 4\n\n Un código fuente:\n```cpp\n#include <iostream>\nint main() {\n    std::cout << \"Hola mundo!\" << std::endl;\n    return 0;\n}\n```";

    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

