Aquí te presento un ejemplo de cómo leer un archivo de texto línea por línea en C++ y contar el número de apariciones de una palabra específica:

```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    // Abrir el archivo de texto
    string filename;
    cout << "Introduce el nombre del archivo: ";
    cin >> filename;

    ifstream file(filename);
    if (!file.is_open()) {
        cerr << "Error al abrir el archivo: " << filename << endl;
        return 1;
    }

    // Palabra a buscar
    string search_word;
    cout << "Introduce la palabra a buscar: ";
    cin >> search_word;

    int count = 0; // Contador para el número de apariciones

    // Leer línea por línea y contar apariciones
    string line;
    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(search_word, pos)) != string::npos) {
            count++;
            pos += search_word.length();
        }
    }

    // Mostrar resultado
    cout << "El número de apariciones de \"" << search_word << "\" en " << filename << " es: " << count << endl;

    file.close(); // Cerrar el archivo

    return 0;
}
```

