Aquí te presento un programa en C++ para encontrar los elementos comunes en dos matrices sin utilizar ninguna estructura de datos adicional:

```cpp
#include <iostream>
#include <algorithm>

using namespace std;

int main() {
    int m1_rows, m1_cols, m2_rows, m2_cols;
    cout << "Ingrese el número de filas y columnas para la primera matriz: ";
    cin >> m1_rows >> m1_cols;

    int matrix1[m1_rows][m1_cols];

    cout << "Ingrese los valores para la primera matriz:" << endl;
    for (int I = 0; I < m1_rows; i++) {
        for (int j = 0; j < m1_cols; j++) {
            cin >> matrix1[i][j];
        }
    }

    cout << "Ingrese el número de filas y columnas para la segunda matriz: ";
    cin >> m2_rows >> m2_cols;

    int matrix2[m2_rows][m2_cols];

    cout << "Ingrese los valores para la segunda matriz:" << endl;
    for (int I = 0; I < m2_rows; i++) {
        for (int j = 0; j < m2_cols; j++) {
            cin >> matrix2[i][j];
        }
    }

    // Comprobar que las matrices tienen el mismo número de columnas
    if (m1_cols != m2_cols) {
        cout << "Las matrices no tienen el mismo número de columnas" << endl;
        return 1;
    }

    // Hallar los elementos comunes
    int common[m1_rows + m2_rows];
    int count = 0;
    for (int I = 0; I < m1_rows; i++) {
        for (int j = 0; j < m1_cols; j++) {
            for (int k = 0; k < m2_rows; k++) {
                if (matrix1[i][j] == matrix2[k][j]) {
                    common[count] = matrix1[i][j];
                    count++;
                    break;
                }
            }
        }
    }

    // Eliminar los elementos repetidos
    sort(common, common + count);
    count = unique(common, common + count) - common;

    // Imprimir los elementos comunes
    cout << "Los elementos comunes son: ";
    for (int I = 0; I < count; i++) {
        cout << common[i] << " ";
    }
    cout << endl;

    return 0;
}
```

Este programa toma dos matrices como input y encuentra los elementos comunes entre ellas. Primero, verifica que las matrices tienen el mismo número de columnas. Luego, crea una matriz de tamaño `m1_rows + m2_rows` para almacenar los elementos comunes y recorre las matrices de forma intercalada para encontrar los valores iguales. Luego, elimina los elementos repetidos usando la función `unique` y `sort` de la biblioteca estandar de C++. Finalmente, imprime los elementos comunes encontrados. 

Recuerda que este programa asume que las matrices tienen valores enteros. Si necesitas soportar otros tipos de datos, debes modificar el código adecuadamente.
